/* Fade + rise on entering view. The range is a fixed 220px of scroll (not a % of the
   element), shifted 40px per stagger step, so tall elements in the first screen still finish. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .eightsleep-reveal {
      animation: eightsleep-reveal-rise linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--eightsleep-step, 0) * 40px) entry calc(220px + var(--eightsleep-step, 0) * 40px);
    }
  }
}

@keyframes eightsleep-reveal-rise {
  from {
    opacity: 0;
    translate: 0 var(--eightsleep-rise, 18px);
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}

import type { CSSProperties, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./eightsleep-reveal.css";

export interface EightsleepRevealProps {
  children: ReactNode;
  /** stagger position: each step starts 40px of scroll later */
  step?: number;
  /** how far it rises, in px (18 for text, 24 for list items) */
  rise?: number;
  /** the element to render */
  as?: "div" | "span" | "li" | "p";
  className?: string;
}

export function EightsleepReveal({ children, step = 0, rise = 18, as: Tag = "div", className }: EightsleepRevealProps) {
  const style = { "--eightsleep-step": step, "--eightsleep-rise": `${rise}px` } as CSSProperties;
  return (
    <Tag className={cn("eightsleep-reveal", Tag === "span" && "block", className)} style={style}>
      {children}
    </Tag>
  );
}
